import{_ as t,o as s,c as a,a as e}from"./chunks/framework.DzJZdBQK.js";const m=JSON.parse('{"title":"写作课作业-032","description":"","frontmatter":{"date":"2020-08-20T16:23:09","title":"写作课作业-032","categories":["写作","作业"],"tags":["写作","作业"]},"headers":[],"relativePath":"posts/homework/032.md","filePath":"posts/homework/032.md"}'),l={name:"posts/homework/032.md"};function n(r,o,p,c,i,u){return s(),a("div",null,[...o[0]||(o[0]=[e("blockquote",null,[e("p",null,"8.20写作作业：学习逻辑课“信息幻觉”，结合生活和工作的经历，谈一下自己的感受和思考，如何为我所用？运用一个类比。")],-1),e("p",null,"信息幻觉（Informational Illusion）是认为拥有的信息越多，自己做出的决策就越准确的想法，而这种想法是一种认知偏差，也可称为“知识的诅咒（Curse of Knowledge）”。",-1),e("p",null,"出现信息幻觉的原因是只关注了信息量而忽视了信息的质量。信息收集时可能出现各种偏差，如果获取了过多的单一来源的信息，单一角度的信息，易得的表面信息，反而会降低决策的效果。",-1),e("p",null,"计算机行业中有个叫DDos的攻击（拒绝服务攻击），就是利用大量的伪造的合理请求，使得目标服务器消耗大量资源来处理这些无效请求，进而无法响应其他正常的请求。DDos无法完全防御，只能通过阻挡恶意流量，系统调优和增加缓存等方式来缓解。",-1),e("p",null,"当发生信息幻觉时，我们就像是遭受了DDos攻击，我们的精力被过多的信息所消耗，严重时可能造成雪崩，什么决策也做不了。正如我们只能缓解DDos的影响而无法完全消除一样，我们很难避免信息幻觉，但我们可以深入思考问题的最重要决策因素，根据最重要因素来反向收集信息，就可以过滤很多无用信息，这样能将更多的精力放在成长上——优化和升级自己的系统，提高自己解决问题的能力。",-1)])])}const f=t(l,[["render",n]]);export{m as __pageData,f as default};
